  emails: [ ['subject', 'Subject', 'text', true], ['business_id', 'Business', 'business'], ['sender', 'From email', 'email'], ['recipient', 'To email', 'email', true], ['direction', 'Direction', ['Outbound', 'Inbound']], ['status', 'Tracking status', ['Draft', 'Planned', 'Sent', 'Replied', 'Bounced']], ['occurred_on', 'Message / reply date', 'date'], ['campaign', 'Campaign name'], ['summary', 'Brief message summary', 'textarea'], ['message_type', 'Message type', ['Human', 'Automatic', 'Delivery', 'Form']], ['verification', 'Summary verification', ['Unverified', 'Reviewed']], ['response_status', 'Response status', ['No action', 'Needs our reply', 'Waiting for reply', 'Follow up', 'Closed']], ['next_action', 'Next action', 'textarea'], ['follow_up_on', 'Next contact date', 'date'] ],
